// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(uint128 amount, address actor1, address actor2) public {
        vm.assume(actor1 != address(0) && actor2 != address(0) && actor1 != address(c));
        vm.assume(amount > 0);

        // First Put: must succeed for any admissible input.
        vm.deal(actor1, amount);
        vm.prank(actor1);
        c.Put{value: amount}(0);

        // General rule: after Put completes, the lock is released, so ANY
        // subsequent Put (different actor, different amount) must also succeed.
        vm.deal(actor2, amount);
        vm.prank(actor2);
        bool ok;
        try c.Put{value: amount, gas: 500000}(0) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}
